const x = $json.body ?? $json;
const text = [
  x.companyName, x.description, x.industry, x.country, x.websiteText
].filter(Boolean).join(' ').toLowerCase();

const positive = [
  ['battery', 20], ['energy storage', 25], ['bess', 25], ['solar', 12],
  ['renewable', 12], ['telecom', 8], ['data center', 8], ['distributor', 10],
  ['integrator', 15], ['wholesaler', 10], ['epc', 15], ['utility', 10]
];
const negative = [
  ['consumer electronics', -10], ['retail only', -12], ['student', -25]
];

let score = 0;
const reasons = [];
for (const [term, pts] of positive) {
  if (text.includes(term)) { score += pts; reasons.push('+' + pts + ' ' + term); }
}
for (const [term, pts] of negative) {
  if (text.includes(term)) { score += pts; reasons.push(String(pts) + ' ' + term); }
}
score = Math.max(0, Math.min(100, score));

const segment =
  text.includes('integrator') || text.includes('epc') ? 'SYSTEM_INTEGRATOR' :
  text.includes('distributor') || text.includes('wholesaler') ? 'DISTRIBUTOR' :
  text.includes('telecom') || text.includes('data center') ? 'BACKUP_POWER' :
  text.includes('solar') || text.includes('renewable') ? 'RENEWABLE_ENERGY' :
  'GENERAL_B2B';

return [{
  json: {
    leadId: x.leadId ?? ('lead-' + Date.now()),
    companyName: x.companyName ?? 'Unknown',
    domain: x.domain ?? '',
    country: x.country ?? '',
    segment,
    fitScore: score,
    fitReasons: reasons,
    qualification: score >= 45 ? 'QUALIFIED' : score >= 25 ? 'REVIEW' : 'LOW_FIT',
    source: x.source ?? 'manual-demo',
    raw: x
  }
}];

const x = $json;
const researchPlan = [
  'Verify company identity and official domain',
  'Identify business model and target markets',
  'Find public evidence of battery/energy-storage demand',
  'Identify relevant buyer role (procurement, energy systems, operations, business development)',
  'Collect only public business contact channels',
  'Draft one outreach angle tied to verified evidence'
];

let angle = 'General battery and energy-storage partnership';
if (x.segment === 'SYSTEM_INTEGRATOR') angle = 'OEM/ODM BESS supply + system-integration support';
if (x.segment === 'DISTRIBUTOR') angle = 'Distributor/wholesale battery supply and territory expansion';
if (x.segment === 'BACKUP_POWER') angle = 'Telecom/data-center backup battery reliability and lifecycle';
if (x.segment === 'RENEWABLE_ENERGY') angle = 'Solar/renewable storage pairing and BESS availability';

return [{
  json: {
    ...x,
    researchPlan,
    outreachAngle: angle,
    nextAction: x.qualification === 'QUALIFIED'
      ? 'RESEARCH_AND_PREPARE_OUTREACH'
      : x.qualification === 'REVIEW'
        ? 'HUMAN_REVIEW'
        : 'DROP',
    guardrails: [
      'No purchased contact lists',
      'No private-personal data',
      'No outreach until company identity and business relevance are verified',
      'Deduplicate by company domain before any send'
    ],
    demoStatus: 'PORTFOLIO_DEMO_ONLY'
  }
}];
